+// ---------------------------------------------------------------------------
+// In-memory response cache for /stats/top-customers
+// ---------------------------------------------------------------------------
+
+const CACHE_TTL_MS = 60_000; // 60 seconds
+
+interface CacheEntry {
+  value: TopCustomer[];
+  expiresAt: number;
+}
+
+export class TopCustomersCache {
+  private store = new Map<number, CacheEntry>();
+
+  get(limit: number): TopCustomer[] | undefined {
+    const entry = this.store.get(limit);
+    if (!entry) return undefined;
+    if (Date.now() >= entry.expiresAt) {
+      this.store.delete(limit);
+      return undefined;
+    }
+    return entry.value;
+  }
+
+  set(limit: number, value: TopCustomer[]): void {
+    this.store.set(limit, { value, expiresAt: Date.now() + CACHE_TTL_MS });
+  }
+}
