diff --git a/demo/orders-api/src/db.ts b/demo/orders-api/src/db.ts
index fa3c0a9..a64aa69 100644
--- a/demo/orders-api/src/db.ts
+++ b/demo/orders-api/src/db.ts
@@ -4,4 +4,7 @@ export const CUSTOMERS = 5_000;
 export const ORDERS = 200_000;

+// How often (ms) the materialized view is refreshed in the background.
+export const REFRESH_INTERVAL_MS = 30_000;
+
 // Builds an in memory database with deterministic seed data, so every
 // branch in a Settle run measures against exactly the same rows.
@@ -39,5 +42,34 @@ export async function openDb(): Promise<PGlite> {

     ANALYZE;
+
+    -- Materialized view: top customers by paid revenue over the last 30 days.
+    -- Stored as a regular table so reads are instant (sequential scan of ~5 k rows max).
+    CREATE MATERIALIZED VIEW top_customers_mv AS
+    SELECT c.id          AS customer_id,
+           c.name,
+           sum(o.amount_cents)::int AS revenue_cents,
+           count(*)::int            AS orders
+    FROM   orders o
+    JOIN   customers c ON c.id = o.customer_id
+    WHERE  o.status = 'paid'
+      AND  o.created_at > now() - interval '30 days'
+    GROUP  BY c.id, c.name
+    ORDER  BY revenue_cents DESC;
+
+    -- Index so ORDER BY + LIMIT reads the pre-sorted rows cheaply.
+    CREATE UNIQUE INDEX top_customers_mv_pk ON top_customers_mv (customer_id);
+    CREATE INDEX top_customers_mv_revenue ON top_customers_mv (revenue_cents DESC);
   `);
   return db;
 }
+
+// Refresh the materialized view concurrently so reads are never blocked.
+// Returns a handle that can be cleared to stop the loop (useful in tests).
+export function startRefresh(db: PGlite, intervalMs = REFRESH_INTERVAL_MS): ReturnType<typeof setInterval> {
+  return setInterval(() => {
+    // CONCURRENTLY requires the unique index we created above.
+    db.exec("REFRESH MATERIALIZED VIEW CONCURRENTLY top_customers_mv;").catch((err) => {
+      console.error("materialized view refresh failed:", err);
+    });
+  }, intervalMs);
+}
